using UrlShortener.Api.Domain;

namespace UrlShortener.Api.Persistence;

/// <summary>Storage abstraction. The in-memory implementation can be replaced by SQL without touching the service.</summary>
public interface IUrlRepository
{
    long NextId();

    /// <summary>Atomically adds the link. Returns false when the code already exists.</summary>
    bool TryAdd(ShortLink link);

    ShortLink? Get(string code);

    /// <summary>Finds the latest link created by this client for this exact target (for idempotent create).</summary>
    ShortLink? FindByOwnerAndTarget(string ownerClientId, string targetUrl);

    /// <summary>Marks the link inactive. Returns false if it does not exist.</summary>
    bool Deactivate(string code);

    /// <summary>Compare-and-swap: replaces the stored link only if it still equals <paramref name="expected"/>.</summary>
    bool TryReplace(string code, ShortLink expected, ShortLink updated);
}

using System.Collections.Concurrent;
using UrlShortener.Api.Domain;

namespace UrlShortener.Api.Persistence;

public sealed class InMemoryUrlRepository : IUrlRepository
{
    private readonly ConcurrentDictionary<string, ShortLink> _links = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<(string Owner, string Target), string> _byOwnerAndTarget = new();
    private long _idCounter;

    public long NextId() => Interlocked.Increment(ref _idCounter);

    public bool TryAdd(ShortLink link)
    {
        if (!_links.TryAdd(link.Code, link)) return false;
        _byOwnerAndTarget[(link.OwnerClientId, link.TargetUrl)] = link.Code;
        return true;
    }

    public ShortLink? Get(string code) => _links.TryGetValue(code, out var link) ? link : null;

    public ShortLink? FindByOwnerAndTarget(string ownerClientId, string targetUrl) =>
        _byOwnerAndTarget.TryGetValue((ownerClientId, targetUrl), out var code) ? Get(code) : null;

    public bool Deactivate(string code)
    {
        while (_links.TryGetValue(code, out var current))
        {
            if (!current.IsActive) return true;
            if (_links.TryUpdate(code, current with { IsActive = false }, current)) return true;
        }
        return false;
    }

    public bool TryReplace(string code, ShortLink expected, ShortLink updated) =>
        _links.TryUpdate(code, updated, expected);
}

using UrlShortener.Api.Domain;

namespace UrlShortener.Api.Services;

public enum CreateStatus { Created, Existing, Invalid, AliasTaken }

public sealed record CreateLinkRequest(string? Url, string? Alias = null, int? ExpiresInMinutes = null);

public sealed record CreateResult(CreateStatus Status, ShortLink? Link = null, IReadOnlyList<string>? Errors = null);

public enum ResolveStatus { Redirect, NotFound, Gone }

public sealed record ResolveResult(ResolveStatus Status, string? TargetUrl = null);

public enum DeactivateStatus { Done, NotFound, Forbidden }

public enum ExtendStatus { Done, NotFound, Forbidden, Invalid, Deactivated, NoExpiry, TooLong }

public sealed record ExtendResult(ExtendStatus Status, ShortLink? Link = null, long? RemainingSeconds = null);

public sealed record LinkStats(
    string Code,
    string TargetUrl,
    DateTimeOffset CreatedAt,
    DateTimeOffset? ExpiresAt,
    bool IsActive,
    long TotalClicks,
    DateTimeOffset? LastAccessedAt,
    IReadOnlyDictionary<string, long> DailyClicks,
    long? RemainingSeconds = null);

using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using UrlShortener.Api.Analytics;
using UrlShortener.Api.Domain;
using UrlShortener.Api.Options;
using UrlShortener.Api.Persistence;
using UrlShortener.Api.Validation;

namespace UrlShortener.Api.Services;

/// <summary>Core business logic: create, resolve (with expiry), deactivate, extend and stats.</summary>
public sealed class ShortenerService
{
    private const int MaxCodeCollisionRetries = 20;
    private const int MaxCasRetries = 10_000;

    private readonly IUrlRepository _repo;
    private readonly UrlValidator _urlValidator;
    private readonly ClickRecorder _clicks;
    private readonly AnalyticsStore _analytics;
    private readonly ShortenerOptions _options;
    private readonly TimeProvider _time;
    private readonly ILogger? _audit;

    public ShortenerService(
        IUrlRepository repo,
        UrlValidator urlValidator,
        ClickRecorder clicks,
        AnalyticsStore analytics,
        ShortenerOptions options,
        TimeProvider time,
        ILogger? auditLogger = null)
    {
        _repo = repo;
        _urlValidator = urlValidator;
        _clicks = clicks;
        _analytics = analytics;
        _options = options;
        _time = time;
        _audit = auditLogger;
    }

    public CreateResult Create(CreateLinkRequest request, string clientId)
    {
        var errors = new List<string>();

        var url = _urlValidator.Validate(request.Url);
        if (!url.IsValid) errors.Add(url.Error!);

        string? alias = string.IsNullOrWhiteSpace(request.Alias) ? null : request.Alias.Trim();
        if (alias is not null)
        {
            var aliasError = AliasValidator.Validate(alias);
            if (aliasError is not null) errors.Add(aliasError);
        }

        if (request.ExpiresInMinutes is { } minutes && (minutes < 1 || minutes > _options.MaxExpiryMinutes))
            errors.Add($"expiresInMinutes must be between 1 and {_options.MaxExpiryMinutes}.");

        if (errors.Count > 0) return new CreateResult(CreateStatus.Invalid, Errors: errors);

        var now = _time.GetUtcNow();

        // Idempotent create: same client + same target (and no custom alias) returns the existing live link.
        if (alias is null)
        {
            var existing = _repo.FindByOwnerAndTarget(clientId, url.NormalizedUrl!);
            if (existing is { IsActive: true } && !existing.IsExpired(now))
                return new CreateResult(CreateStatus.Existing, existing);
        }

        DateTimeOffset? expiresAt = request.ExpiresInMinutes is { } m ? now.AddMinutes(m) : null;

        if (alias is not null)
        {
            var link = new ShortLink(alias, url.NormalizedUrl!, now, expiresAt, true, clientId);
            return _repo.TryAdd(link)
                ? new CreateResult(CreateStatus.Created, link)
                : new CreateResult(CreateStatus.AliasTaken, Errors: new[] { "alias is already in use." });
        }

        for (var attempt = 0; attempt < MaxCodeCollisionRetries; attempt++)
        {
            var code = CodeGenerator.FromId(_repo.NextId());
            if (AliasValidator.IsReserved(code)) continue;

            var link = new ShortLink(code, url.NormalizedUrl!, now, expiresAt, true, clientId);
            if (_repo.TryAdd(link)) return new CreateResult(CreateStatus.Created, link);
            // the code collided with a custom alias: move on to the next id
        }

        throw new InvalidOperationException("Could not allocate a unique short code.");
    }

    public ResolveResult Resolve(string code)
    {
        var link = _repo.Get(code);
        if (link is null) return new ResolveResult(ResolveStatus.NotFound);

        var now = _time.GetUtcNow();
        if (!link.IsActive || link.IsExpired(now)) return new ResolveResult(ResolveStatus.Gone);

        _clicks.Enqueue(new ClickEvent(code, now));
        return new ResolveResult(ResolveStatus.Redirect, link.TargetUrl);
    }

    public DeactivateStatus Deactivate(string code, string clientId)
    {
        var link = _repo.Get(code);
        if (link is null) return DeactivateStatus.NotFound;
        if (!string.Equals(link.OwnerClientId, clientId, StringComparison.Ordinal)) return DeactivateStatus.Forbidden;
        _repo.Deactivate(code);
        return DeactivateStatus.Done;
    }

    /// <summary>
    /// Extends the expiry by <paramref name="additionalSeconds"/>. Check order: 404, 403, 400, 409.
    /// Expired (but active) links are revived from now. Uses compare-and-swap so concurrent extends lose no updates.
    /// </summary>
    public ExtendResult ExtendExpiry(string code, string clientId, long? additionalSeconds)
    {
        var maxSeconds = _options.MaxExpiryMinutes * 60L;

        for (var attempt = 0; attempt < MaxCasRetries; attempt++)
        {
            var link = _repo.Get(code);
            if (link is null) return Audit(ExtendStatus.NotFound, code, clientId, null, null, additionalSeconds);
            if (!string.Equals(link.OwnerClientId, clientId, StringComparison.Ordinal))
                return Audit(ExtendStatus.Forbidden, code, clientId, link.ExpiresAt, null, additionalSeconds);

            if (additionalSeconds is not { } add || add <= 0)
                return Audit(ExtendStatus.Invalid, code, clientId, link.ExpiresAt, null, additionalSeconds);
            if (add > maxSeconds)
                return Audit(ExtendStatus.TooLong, code, clientId, link.ExpiresAt, null, additionalSeconds);

            if (!link.IsActive) return Audit(ExtendStatus.Deactivated, code, clientId, link.ExpiresAt, null, additionalSeconds);
            if (link.ExpiresAt is not { } current)
                return Audit(ExtendStatus.NoExpiry, code, clientId, null, null, additionalSeconds);

            var now = _time.GetUtcNow();
            var baseTime = current > now ? current : now;
            var newExpiry = baseTime.AddSeconds(add);
            if ((newExpiry - now).TotalSeconds > maxSeconds)
                return Audit(ExtendStatus.TooLong, code, clientId, current, null, additionalSeconds);

            var updated = link with { ExpiresAt = newExpiry };
            if (_repo.TryReplace(code, link, updated))
            {
                return Audit(ExtendStatus.Done, code, clientId, current, newExpiry, additionalSeconds, updated, Remaining(newExpiry, now));
            }
            // lost the race: re-read and retry
        }

        throw new InvalidOperationException("Could not extend expiry due to contention.");
    }

    private ExtendResult Audit(ExtendStatus status, string code, string clientId, DateTimeOffset? previous,
        DateTimeOffset? next, long? add, ShortLink? link = null, long? remaining = null)
    {
        _audit?.LogInformation(
            "audit action={Action} at={At} code={Code} actor={ActorHash} outcome={Outcome} previousExpiresAt={Previous} newExpiresAt={New} additionalSeconds={Additional}",
            "expiry.extend", _time.GetUtcNow(), Sanitize(code), ActorHash(clientId), status.ToString(), previous, next, add);
        return new ExtendResult(status, link, remaining);
    }

    private static string Sanitize(string value)
    {
        var v = value.Length > 64 ? value[..64] : value;
        var sb = new StringBuilder(v.Length);
        foreach (var c in v) sb.Append(char.IsLetterOrDigit(c) || c == '-' || c == '_' ? c : '?');
        return sb.ToString();
    }

    private static string ActorHash(string clientId) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(clientId)))[..12];

    private static long Remaining(DateTimeOffset expiresAt, DateTimeOffset now)
    {
        var secs = (long)Math.Floor((expiresAt - now).TotalSeconds);
        return secs < 0 ? 0 : secs;
    }

    /// <summary>Link metadata, or null for unknown codes. Does not count as a click.</summary>
    public ShortLink? GetMetadata(string code) => _repo.Get(code);

    public LinkStats? GetStats(string code)
    {
        var link = _repo.Get(code);
        if (link is null) return null;
        var a = _analytics.Get(code);
        long? remaining = link.ExpiresAt is { } e ? Remaining(e, _time.GetUtcNow()) : null;
        return new LinkStats(link.Code, link.TargetUrl, link.CreatedAt, link.ExpiresAt, link.IsActive,
            a.TotalClicks, a.LastAccessedAt, a.DailyClicks, remaining);
    }
}

using Microsoft.Extensions.Options;
using UrlShortener.Api.Analytics;
using UrlShortener.Api.Endpoints;
using UrlShortener.Api.Options;
using UrlShortener.Api.Persistence;
using UrlShortener.Api.Reliability;
using UrlShortener.Api.Services;
using UrlShortener.Api.Validation;

namespace UrlShortener.Api;

/// <summary>Composition root. Kept separate from Program so tests can host the API in-process.</summary>
public static class AppHost
{
    public static WebApplication Build(string[] args, Action<ShortenerOptions>? configure = null, TimeProvider? time = null)
    {
        var builder = WebApplication.CreateBuilder(args);

        builder.Services.Configure<ShortenerOptions>(builder.Configuration.GetSection("Shortener"));
        if (configure is not null) builder.Services.PostConfigure(configure);

        builder.WebHost.ConfigureKestrel((ctx, kestrel) =>
        {
            var opts = ctx.Configuration.GetSection("Shortener").Get<ShortenerOptions>() ?? new ShortenerOptions();
            configure?.Invoke(opts);
            kestrel.Limits.MaxRequestBodySize = opts.MaxRequestBodyBytes;
            kestrel.AddServerHeader = false;
        });

        builder.Services.AddProblemDetails();
        builder.Services.AddSingleton(time ?? TimeProvider.System);
        builder.Services.AddSingleton<IUrlRepository, InMemoryUrlRepository>();
        builder.Services.AddSingleton<AnalyticsStore>();
        builder.Services.AddSingleton(sp => new ClickRecorder(sp.GetRequiredService<IOptions<ShortenerOptions>>().Value.ClickQueueCapacity));
        builder.Services.AddHostedService<ClickProcessor>();
        builder.Services.AddSingleton(sp => new UrlValidator(sp.GetRequiredService<IOptions<ShortenerOptions>>().Value.MaxUrlLength));
        builder.Services.AddSingleton(sp =>
        {
            var o = sp.GetRequiredService<IOptions<ShortenerOptions>>().Value;
            return new FixedWindowRateLimiter(o.RateLimitPerWindow, TimeSpan.FromSeconds(o.RateLimitWindowSeconds), sp.GetRequiredService<TimeProvider>());
        });
        builder.Services.AddSingleton(sp => new ShortenerService(
            sp.GetRequiredService<IUrlRepository>(),
            sp.GetRequiredService<UrlValidator>(),
            sp.GetRequiredService<ClickRecorder>(),
            sp.GetRequiredService<AnalyticsStore>(),
            sp.GetRequiredService<IOptions<ShortenerOptions>>().Value,
            sp.GetRequiredService<TimeProvider>(),
            sp.GetRequiredService<ILoggerFactory>().CreateLogger("UrlShortener.Audit")));

        var app = builder.Build();

        app.UseExceptionHandler();
        app.Use(async (context, next) =>
        {
            context.Response.Headers["X-Content-Type-Options"] = "nosniff";
            context.Response.Headers["Cache-Control"] = "no-store";
            await next();
        });

        ShortLinkEndpoints.Map(app);
        return app;
    }
}

namespace UrlShortener.Api.Endpoints;

/// <summary>Response contracts (public API shape).</summary>
public sealed record CreateLinkResponse(string Code, string ShortUrl, string TargetUrl, DateTimeOffset? ExpiresAt, bool Created);

/// <summary>Link metadata without analytics (GET /api/urls/{code}). The owner id is deliberately not exposed.</summary>
public sealed record LinkMetadataResponse(
    string Code, string ShortUrl, string TargetUrl, DateTimeOffset CreatedAt, DateTimeOffset? ExpiresAt, bool IsActive);

/// <summary>Request body of the extend endpoint (parsed manually so malformed input yields 400).</summary>
public sealed record ExtendExpiryRequest(long? AdditionalSeconds);

public sealed record ExtendExpiryResponse(string Code, DateTimeOffset? ExpiresAt, long? RemainingSeconds);

using System.Text.Json;
using Microsoft.Extensions.Options;
using UrlShortener.Api.Options;
using UrlShortener.Api.Reliability;
using UrlShortener.Api.Services;

namespace UrlShortener.Api.Endpoints;

public static class ShortLinkEndpoints
{
    private const int MaxClientIdLength = 64;

    public static void Map(WebApplication app)
    {
        app.MapGet("/health", () => Results.Ok(new { status = "healthy" }));

        var api = app.MapGroup("/api/urls");
        api.MapPost("", CreateAsync);
        api.MapGet("/{code}", GetMetadata);
        api.MapGet("/{code}/analytics", GetStats);
        api.MapGet("/{code}/stats", GetStats); // kept for backward compatibility
        api.MapDelete("/{code}", Deactivate);
        api.MapPost("/{code}/extend", ExtendAsync);
        api.MapPut("/{code}/expiry", ExtendAsync); // canonical alias

        // Canonical redirect route; the single-segment form is kept for short URLs already handed out.
        app.MapGet("/r/{code}", Redirect);
        // Single-segment catch-all must be registered after the literal routes above.
        app.MapGet("/{code}", Redirect);
    }

    private static IResult CreateAsync(
        CreateLinkRequest? request,
        HttpContext http,
        ShortenerService service,
        FixedWindowRateLimiter limiter,
        IOptions<ShortenerOptions> options)
    {
        var clientId = GetClientId(http);

        if (!limiter.TryAcquire(clientId, out var retryAfter))
        {
            http.Response.Headers.RetryAfter = Math.Ceiling(retryAfter.TotalSeconds).ToString("0");
            return Results.Problem("Rate limit exceeded.", statusCode: StatusCodes.Status429TooManyRequests);
        }

        if (request is null)
            return Results.ValidationProblem(new Dictionary<string, string[]> { ["body"] = new[] { "request body is required." } });

        var result = service.Create(request, clientId);
        switch (result.Status)
        {
            case CreateStatus.Invalid:
                return Results.ValidationProblem(new Dictionary<string, string[]> { ["request"] = result.Errors!.ToArray() });
            case CreateStatus.AliasTaken:
                return Results.Problem(result.Errors![0], statusCode: StatusCodes.Status409Conflict);
        }

        var link = result.Link!;
        var baseUrl = options.Value.BaseUrl?.TrimEnd('/') ?? $"{http.Request.Scheme}://{http.Request.Host}";
        var body = new CreateLinkResponse(link.Code, $"{baseUrl}/r/{link.Code}", link.TargetUrl, link.ExpiresAt,
            result.Status == CreateStatus.Created);

        return result.Status == CreateStatus.Created
            ? Results.Created($"/api/urls/{link.Code}", body)
            : Results.Ok(body);
    }

    private static IResult GetMetadata(string code, HttpContext http, ShortenerService service, IOptions<ShortenerOptions> options)
    {
        if (service.GetMetadata(code) is not { } link) return Results.NotFound();
        var baseUrl = options.Value.BaseUrl?.TrimEnd('/') ?? $"{http.Request.Scheme}://{http.Request.Host}";
        return Results.Ok(new LinkMetadataResponse(link.Code, $"{baseUrl}/r/{link.Code}", link.TargetUrl, link.CreatedAt,
            link.ExpiresAt, link.IsActive));
    }

    private static IResult Redirect(string code, ShortenerService service)
    {
        var result = service.Resolve(code);
        return result.Status switch
        {
            ResolveStatus.Redirect => Results.Redirect(result.TargetUrl!, permanent: false),
            ResolveStatus.Gone => Results.Problem("This link has expired or was deactivated.", statusCode: StatusCodes.Status410Gone),
            _ => Results.NotFound()
        };
    }

    private static IResult GetStats(string code, ShortenerService service) =>
        service.GetStats(code) is { } stats ? Results.Ok(stats) : Results.NotFound();

    private static IResult Deactivate(string code, HttpContext http, ShortenerService service) =>
        service.Deactivate(code, GetClientId(http)) switch
        {
            DeactivateStatus.Done => Results.NoContent(),
            DeactivateStatus.Forbidden => Results.Problem("Only the creator can deactivate this link.", statusCode: StatusCodes.Status403Forbidden),
            _ => Results.NotFound()
        };

    private static async Task<IResult> ExtendAsync(string code, HttpContext http, ShortenerService service, FixedWindowRateLimiter limiter)
    {
        var clientId = GetClientId(http);

        if (!limiter.TryAcquire("extend:" + clientId, out var retryAfter))
        {
            http.Response.Headers.RetryAfter = Math.Ceiling(retryAfter.TotalSeconds).ToString("0");
            return Results.Problem("Rate limit exceeded.", statusCode: StatusCodes.Status429TooManyRequests);
        }

        // Parsed by hand so that missing, malformed or non-numeric input maps to null (-> 400), never 500.
        long? seconds = null;
        try
        {
            using var doc = await JsonDocument.ParseAsync(http.Request.Body, cancellationToken: http.RequestAborted);
            if (doc.RootElement.ValueKind == JsonValueKind.Object)
            {
                foreach (var prop in doc.RootElement.EnumerateObject())
                {
                    if (!string.Equals(prop.Name, "additionalSeconds", StringComparison.OrdinalIgnoreCase)) continue;
                    if (prop.Value.ValueKind == JsonValueKind.Number && prop.Value.TryGetInt64(out var v)) seconds = v;
                    break;
                }
            }
        }
        catch (JsonException)
        {
            seconds = null;
        }

        var result = service.ExtendExpiry(code, clientId, seconds);
        switch (result.Status)
        {
            case ExtendStatus.Done:
                return Results.Ok(new ExtendExpiryResponse(result.Link!.Code, result.Link.ExpiresAt, result.RemainingSeconds));
            case ExtendStatus.Forbidden:
                return Results.Problem("Only the creator can extend this link.", statusCode: StatusCodes.Status403Forbidden);
            case ExtendStatus.Invalid:
                return Results.ValidationProblem(new Dictionary<string, string[]> { ["additionalSeconds"] = new[] { "additionalSeconds must be a positive whole number." } });
            case ExtendStatus.TooLong:
                return Results.ValidationProblem(new Dictionary<string, string[]> { ["additionalSeconds"] = new[] { "resulting lifetime exceeds the maximum allowed." } });
            case ExtendStatus.Deactivated:
                return Results.Problem("The link is deactivated and cannot be extended.", statusCode: StatusCodes.Status409Conflict);
            case ExtendStatus.NoExpiry:
                return Results.Problem("The link has no expiry to extend.", statusCode: StatusCodes.Status409Conflict);
            default:
                return Results.NotFound();
        }
    }

    /// <summary>
    /// Placeholder identity: X-Client-Id header, else remote IP. Real authentication is out of scope for
    /// the prototype (documented limitation) - this value is spoofable.
    /// </summary>
    internal static string GetClientId(HttpContext http)
    {
        var header = http.Request.Headers["X-Client-Id"].ToString().Trim();
        if (header.Length > 0) return header.Length > MaxClientIdLength ? header[..MaxClientIdLength] : header;
        return http.Connection.RemoteIpAddress?.ToString() ?? "unknown";
    }
}
